const all = $('Merge Leads1').all().map(i => i.json);
const pending = $input.all().map(i => i.json);

const seenIds    = new Map();
const seenPhones = new Map();
for (const row of all) {
  if (row.lead_id) seenIds.set(String(row.lead_id).trim(), row);
  if (row.phone)   seenPhones.set(String(row.phone).trim(), row);
}

// Prefijos por pais para normalizar E.164
const COUNTRY_PREFIX = {
  'venezuela': '+58', 'vzla': '+58', 've': '+58',
  'mexico':    '+52', 'mx':   '+52',
  'colombia':  '+57', 'co':   '+57',
  'usa':       '+1',  'us':   '+1',
  'spain':     '+34', 'es':   '+34',
  'india':     '+91', 'in':   '+91',
};

const out = [];
for (const c of pending) {
  const errors   = [];
  const fullName = String(c.full_name || '').trim();
  const country  = String(c.country   || '').trim();
  const leadId   = String(c.lead_id   || '').trim();

  // Normalizar idioma: LATAM = es, India = hi, default es
  let language = String(c.language || '').trim().toLowerCase();
  const countryLow = country.toLowerCase();
  if (!language || language === 'hi') {
    if (['india','in'].includes(countryLow)) language = 'hi';
    else language = 'es';
  }

  // Normalizar telefono E.164
  let phone = String(c.phone || '').replace(/[^0-9+]/g, '');
  if (phone && !phone.startsWith('+')) {
    const prefix = COUNTRY_PREFIX[countryLow];
    if (prefix) {
      // Quitar el codigo de pais si ya viene pegado al numero
      const prefixDigits = prefix.replace('+', '');
      if (phone.startsWith(prefixDigits) && phone.length > prefixDigits.length + 6) {
        phone = '+' + phone;
      } else {
        phone = prefix + phone;
      }
    } else if (phone.length >= 8 && phone.length <= 15) {
      phone = '+' + phone;
    }
  }

  // Validaciones
  if (!leadId)   errors.push('missing lead_id');
  //if (!fullName) errors.push('missing full_name');
  if (!phone)    errors.push('missing phone');
  if (!country)  errors.push('missing country');
  if (phone && !/^\+[1-9]\d{7,14}$/.test(phone)) errors.push('invalid phone format: ' + phone);

  // Dedup
  const isActive = (s) => s && !['', 'PENDING_VALIDATION', 'INVALID_LEAD'].includes(String(s).toUpperCase());
  const dupId = seenIds.get(leadId);
  const dupPh = seenPhones.get(phone);
  if (dupId && isActive(dupId.status) && String(dupId.row_number || '') !== String(c.row_number || '')) {
    errors.push('duplicate lead_id');
  } else if (dupPh && isActive(dupPh.status) && String(dupPh.row_number || '') !== String(c.row_number || '')) {
    errors.push('duplicate phone');
  }

  const valid = errors.length === 0;
  out.push({ json: {
    lead_id:   leadId,
    phone,
    full_name: fullName,
    country,
    language,
    _valid:    valid,
    _errors:   errors.join('; '),
    status:    valid ? 'READY_TO_CALL' : 'INVALID_LEAD',
    notes:     valid ? 'Validated OK' : ('VALIDATION FAIL: ' + errors.join('; '))
  }});
}
return out;

